INSERT INTO `produtos` VALUES (1,'Greatest Hits','2Pac','Greatest Hits','CASSETE',1998,99.90,'../imagens/capas/greatest_hits.jpg','Coletânea que reúne alguns dos maiores sucessos de 2Pac, passando por diferentes momentos de sua carreira e mostrando sua força como rapper e compositor.',4),(2,'All Eyez on Me','2Pac','All Eyez on Me','CASSETE',1996,89.90,'https://coverartarchive.org/release-group/e2621417-9236-36b4-9f9e-376c416dc4b0/front-500','Um dos trabalhos mais marcantes de 2Pac, apresentado originalmente como um álbum duplo e conhecido por sua mistura de rap, narrativa urbana e produção da Costa Oeste.',4),(3,'R U Still Down? (Remember Me)','2Pac','R U Still Down? (Remember Me)','CASSETE',1997,79.90,'https://coverartarchive.org/release-group/1707088d-7938-3b91-995c-9a112a2b4f34/front-500','Álbum que reúne gravações de diferentes períodos da carreira de 2Pac, explorando temas pessoais, sociais e a realidade das ruas.',4),(4,'Strictly 4 My N.I.G.G.A.Z...','2Pac','Strictly 4 My N.I.G.G.A.Z...','CASSETE',1993,79.90,NULL,'Segundo álbum de estúdio de 2Pac, marcado por sua energia característica e por letras que abordam a vida nas ruas, questões sociais e sua identidade.',4),(5,'The Don Killuminati: The 7 Day Theory','2Pac','The Don Killuminati: The 7 Day Theory','VINIL',1996,129.90,'../imagens/capas/the_don_killuminati.jpg','Álbum lançado sob o nome Makaveli, conhecido por sua atmosfera mais sombria, letras intensas e produção característica do período final da carreira de 2Pac.',4),(6,'Super Trouper','ABBA','Super Trouper','CASSETE',1980,89.90,'../imagens/capas/super_trouper.jpg','Álbum de 1980 que apresenta alguns dos grandes sucessos do ABBA, combinando pop melódico, harmonias vocais e produções características da banda.',3),(7,'Arrival','ABBA','Arrival','CASSETE',1976,89.90,NULL,'Um dos álbuns mais conhecidos do ABBA, reunindo clássicos do pop dos anos 1970 e consolidando a sonoridade característica do grupo.',3),(8,'Voulez-Vous','ABBA','Voulez-Vous','CASSETE',1979,89.90,'https://coverartarchive.org/release-group/e0da0775-8abe-30ae-bcf9-707a6a8a41e5/front-500','Álbum que incorpora elementos da música disco à sonoridade pop do ABBA, criando uma coleção dançante e marcante do final dos anos 1970.',3),(9,'ABBA','ABBA','ABBA','CD',1975,64.90,'../imagens/capas/abba.jpg','Terceiro álbum de estúdio do grupo sueco, representando uma fase importante na construção da identidade pop que marcaria a carreira do ABBA.',3),(10,'The Album','ABBA','The Album','CASSETE',1977,79.90,NULL,'Trabalho que combina o pop característico do ABBA com composições mais elaboradas e algumas das canções mais lembradas da banda.',3),(11,'Waterloo','ABBA','Waterloo','VINIL',1974,109.90,'../imagens/capas/waterloo.jpg','Álbum que marcou uma etapa decisiva na carreira do ABBA, trazendo a música que deu ao grupo grande destaque internacional.',3),(12,'Dirt','Alice In Chains','Dirt','CASSETE',1992,89.90,'https://coverartarchive.org/release-group/92d8f0c4-8c64-3bee-bee1-812a70e77efa/front-500','Um dos trabalhos mais importantes do Alice in Chains, marcado por riffs pesados, atmosfera sombria e letras introspectivas.',1),(13,'Facelift','Alice In Chains','Facelift','CASSETE',1990,79.90,'../imagens/capas/facelift.jpg','Álbum de estreia do Alice in Chains, combinando elementos do hard rock e do grunge com vocais marcantes e guitarras pesadas.',1),(14,'Jar of Flies','Alice In Chains','Jar of Flies','CASSETE',1994,79.90,NULL,'EP conhecido por sua atmosfera melancólica e por explorar uma abordagem mais acústica e introspectiva da banda.',1),(15,'Alice in Chains','Alice In Chains','Alice in Chains','CD',1995,89.90,'../imagens/capas/alice_in_chains.jpg','Álbum homônimo que apresenta uma sonoridade pesada e sombria, com forte presença de guitarras e vocais característicos da banda.',1),(16,'Unplugged','Alice In Chains','Unplugged','CASSETE',1996,99.90,'../imagens/capas/alice_unplugged.jpg','Registro acústico que apresenta versões mais intimistas das músicas do Alice in Chains, destacando a força das composições.',1),(17,'Abbey Road','The Beatles','Abbey Road','CASSETE',1969,99.90,'../imagens/capas/abbey_road.jpg','Um dos álbuns mais celebrados dos Beatles, conhecido por suas composições marcantes, produção sofisticada e pela famosa sequência final de músicas.',1),(18,'Please Please Me','The Beatles','Please Please Me','VINIL',1963,149.90,NULL,'Please Please Me é um trabalho de The Beatles, lançado em sua respectiva fase da carreira, reunindo características marcantes de sua sonoridade e identidade artística.',1),(19,'Sgt. Pepper’s Lonely Hearts Club Band','The Beatles','Sgt. Pepper’s Lonely Hearts Club Band','CASSETE',1967,99.90,'https://coverartarchive.org/release-group/9f7a4c28-8fa2-3113-929c-c47a9f7982c3/front-500','Sgt. Pepper’s Lonely Hearts Club Band é um trabalho de The Beatles, lançado em sua respectiva fase da carreira, reunindo características marcantes de sua sonoridade e identidade artística.',1),(20,'Rubber Soul','The Beatles','Rubber Soul','CASSETE',1965,89.90,'https://coverartarchive.org/release-group/dca03435-8adb-30a5-ba82-5a162267ff38/front-500','Álbum que representa uma fase de amadurecimento artístico dos Beatles, combinando folk, rock e letras mais introspectivas.',1),(21,'The Beatles (White Album)','The Beatles','The Beatles (White Album)','CASSETE',1968,99.90,'../imagens/capas/white_album.jpg','The Beatles (White Album) é um trabalho de The Beatles, lançado em sua respectiva fase da carreira, reunindo características marcantes de sua sonoridade e identidade artística.',1),(22,'Revolver','The Beatles','Revolver','CASSETE',1966,89.90,'../imagens/capas/revolver.jpg','Trabalho que mostra os Beatles experimentando diferentes estilos, técnicas de estúdio e novas possibilidades sonoras.',1),(23,'Help!','The Beatles','Help!','CASSETE',1965,79.90,'../imagens/capas/help.jpg','Help! é um trabalho de The Beatles, lançado em sua respectiva fase da carreira, reunindo características marcantes de sua sonoridade e identidade artí